'use strict';
const s=(heading,paragraphs,extra={})=>({heading,paragraphs,...extra});
const code=(title,text,lang='java')=>({title,text,lang});
// Hand-authored lesson plans. Full files are embedded from the compiled projects by the builder.
const application=[
['Request Validation','Now we are going to stop invalid requests before they reach the order service. A quantity of zero is valid JSON, but it is not a valid order.',[
s('What does validation check?',['JSON parsing checks whether a request can be read. Bean Validation checks whether its values satisfy our rules. We will require a product name and allow between 1 and 20 items.']),
s('Create the request record',['Open OrderController.java. CreateOrder is a request DTO: it describes the input contract without exposing the persistence entity. @NotBlank rejects missing or whitespace-only names; @Min and @Max bound the quantity. @Valid on the controller parameter triggers these checks before create executes.'],{files:['OrderController.java']}),
s('Return useful field errors',['Open ApiErrors.java. Spring raises MethodArgumentNotValidException for a failed request body. The advice collects each field and message into a ProblemDetail response with HTTP 400. The client can display the errors next to its form fields.'],{files:['ApiErrors.java']}),
s('Try valid and invalid input',['Send the example request, then change quantity to 0. The valid request returns 201; the invalid request returns 400 and an errors array. Confirm that the invalid request did not create an order.'],{request:['POST','/api/v1/orders',{product:'Spring Boot Book',quantity:2}],exercise:'Add @Size(max=100) to a customer note field. Test both the boundary and one character beyond it.'})]],
['REST API Design','Now we will make the order API predictable for its callers. The URL, HTTP status, and response body are all part of the contract.',[
s('Choose a resource and version',['An order is a resource, so the collection is /api/v1/orders and one order is /api/v1/orders/{id}. The v1 prefix leaves a clear place for an incompatible future contract. Do not create a new version for every internal refactoring.']),
s('Use status codes deliberately',['POST returns 201 Created with a Location header. GET returns 200. A missing or inaccessible order returns 404. Invalid fields return 400; a stale cancellation returns 409. These distinctions let callers choose the right response.'],{files:['OrderController.java','ApiErrors.java']}),
s('Keep ownership at the service boundary',['OrderService.owned checks the authenticated owner before returning an order. We return 404 for another user’s order so the endpoint does not confirm that their ID exists. Never trust an owner field supplied in JSON.'],{files:['OrderService.java']}),
s('Paginate the collection',['page starts at zero. size is bounded to prevent one request loading the entire table. The server fixes the sort to descending ID in this example; clients cannot inject arbitrary sort expressions.'],{request:['GET','/api/v1/orders?page=0&size=5'],exercise:'Create six orders, request two pages of size five, and check that the final page contains one order.'})]],
['OpenAPI and Swagger UI','Now we are going to make our API discoverable. Instead of asking another developer to guess the request fields, we will publish a machine-readable contract.',[
s('What is OpenAPI?',['OpenAPI describes paths, parameters, schemas and responses. Swagger UI displays that document as an interactive page. The document describes the API; it does not enforce authorization or validation.']),
s('Add the compatible dependency',['The continuation uses Boot 3.5.16 and springdoc 2.8.17. Open pom.xml and locate springdoc-openapi-starter-webmvc-ui. Reload Maven, start the application, and open /v3/api-docs and /swagger-ui/index.html.'],{files:['pom.xml']}),
s('Read the generated contract',['Find POST /api/v1/orders. Compare the request schema with CreateOrder, including its required fields and numeric limits. The current UI exposes documentation publicly for local learning; restrict it when deploying private APIs.']),
s('Verify the document',['CommerceTest checks that the generated document includes the order collection. A document that loads but omits an endpoint is still an incomplete contract.'],{files:['CommerceTest.java'],exercise:'Add a description and documented 409 response to cancellation, then inspect the generated JSON.'})]],
['Database Migrations with Flyway','Now we will give the database a version history. Application deployment should not depend on somebody remembering which SQL commands to run.',[
s('What is a migration?',['A migration is an ordered schema change. Flyway records completed versions and applies new ones. V1__commerce.sql creates the first tables; a later change belongs in V2, rather than editing a migration already applied to a shared database.']),
s('Create the first schema',['Place the SQL file in src/main/resources/db/migration. The order table includes a version for concurrency control and a timestamp for creation. Token hashes are stored separately from account passwords.'],{files:['db/migration/V1__commerce.sql']}),
s('Let Hibernate validate',['Set spring.jpa.hibernate.ddl-auto=validate. Flyway owns schema changes; Hibernate checks that mappings agree with them. Avoid combining automatic update with migrations and hoping the two mechanisms stay consistent.'],{files:['application.properties','PurchaseOrder.java']}),
s('Use PostgreSQL',['Start the postgres Compose service and activate the postgres profile. Set DB_PASSWORD locally first. The default file-backed H2 database remains useful for learning without Docker.'],{files:['application-postgres.properties','../compose.yaml'],exercise:'Add a nullable note column in V2__order_note.sql, map it on the entity, and restart twice. Verify that V2 runs once.'})]],
['Advanced JPA and Fetch Planning','Now we will separate database work from response serialization. A query that looks small in Java can still execute many SQL statements.',[
s('Understand the N+1 problem',['Suppose a page contains ten applicants and each applicant’s resume is loaded separately. One collection query plus ten association queries makes eleven queries. Use the Applicant relationships from the original course to reproduce this with SQL logging.']),
s('Load what the use case needs',['For a single applicant detail, an @EntityGraph can load the requested association with the entity. For list screens, prefer DTO projections containing only the fields displayed. Avoid collection fetch joins combined blindly with pagination; page parent IDs first, then fetch details.'],{code:code('Add to the ApplicantRepository from the relationship lessons','@EntityGraph(attributePaths = "resume")\n@Query("select a from Applicant a where a.id = :id")\nOptional<Applicant> findDetail(@Param("id") Long id);')}),
s('Close the persistence boundary',['The commerce project disables open-in-view. Do not rely on serialization to fetch lazy associations after the service returns. Map entities to response DTOs inside a read-only service transaction when associations are needed.'],{files:['application.properties','Orders.java','OrderLine.java','OrderDetail.java']}),
s('Audit deliberately',['PurchaseOrder records createdAt when it is created. OrderDetail maps the fetched lines to a response DTO inside a read-only transaction, so serialization never fetches them lazily. A wider audit can use @CreatedDate, @LastModifiedDate and an auditor provider for the current user. Decide which changes need a business audit trail; a timestamp alone cannot explain who changed what.'],{files:['PurchaseOrder.java'],exercise:'Measure SQL counts before and after adding the Applicant detail fetch plan. Keep a test that detects the extra queries.'})]],
['Concurrency and Locking','Now imagine two browser tabs changing the same order. We need to detect stale decisions rather than silently overwrite one change.',[
s('Optimistic locking',['@Version adds a revision to the entity. Hibernate includes the old revision when updating and rejects an update if another transaction has already changed it. Return 409 and ask the client to reload rather than blindly retrying a business decision.'],{files:['PurchaseOrder.java','ApiErrors.java']}),
s('Pessimistic locking',['Orders.lock requests PESSIMISTIC_WRITE. Call it inside a transaction: the row stays locked until that transaction completes. OrderService.cancel also checks the client’s expected revision and the legal source state.'],{files:['Orders.java','OrderService.java']}),
s('Keep locks short',['PaymentService currently holds the order lock during the gateway call to make the first local example easy to trace. The client has bounded timeouts, but slow calls still occupy the transaction. The distributed section replaces this with durable states and independent transactions.']),
s('Try a stale cancellation',['Create an order, read its version, then request cancellation with a different version. Expect 409 and an unchanged PENDING state. A network retry and a stale business update are different problems.'],{request:['POST','/api/v1/orders/1/cancel?version=99'],exercise:'Run two transactions that both load the same version. Commit the first, then assert that the second cannot overwrite it.'})]],
['Integration Testing and Testcontainers','Now we will test the boundaries that a mocked repository cannot check: request validation, security, SQL mappings, and migrations.',[
s('Choose the test boundary',['A unit test isolates one class. @SpringBootTest starts the application context. MockMvc runs requests through Spring MVC and the security chain without opening a public server port.'],{files:['CommerceTest.java']}),
s('Replace only the external boundary',['CommerceTest replaces the mail sender and payment client. The real controllers, authentication service, migrations and database participate. A signed fixture webhook proves our handler behavior; it does not prove a real Stripe account is configured.']),
s('Run against PostgreSQL',['PostgresIT starts a disposable PostgreSQL container and registers its JDBC settings. Run mvn -Dtest=PostgresIT test when Docker is running. This test is opt-in because this environment has no Docker executable.'],{files:['PostgresIT.java']}),
s('Test failures as well as success',['The suite checks ownership, invalid input, stale updates, token rotation and duplicate webhooks. Each test protects an observable behavior rather than simply repeating implementation details.'],{exercise:'Add a test proving a refund request for an unpaid order returns 409 and never calls the payment client.'})]],
['Calling External APIs','Now the application needs data from another server. An HTTP call can fail before a response, after a response, or while the remote operation is still running.',[
s('Build a bounded client',['PaymentClient creates a RestClient with connect and read timeouts. A connect timeout limits establishing the connection; a read timeout bounds waiting for response data. Neither guarantees that the remote operation did not execute.'],{files:['PaymentClient.java']}),
s('Keep provider details behind an adapter',['The service calls checkout(order), not a URL assembled in the controller. The adapter creates the form fields and reads the provider response. Tests can replace this one boundary without mocking the whole application.']),
s('Send a stable operation key',['The checkout idempotency key is derived from the stored order ID. Repeating the same business operation should reuse that key. A new random key on every HTTP retry would allow duplicate remote work.']),
s('Inspect the local test',['The checkout test verifies that two requests reuse the saved session. For an HTTP contract test, point payment.base-url at a local stub and assert the form body and Idempotency-Key header.'],{exercise:'Return a 503 and then a success from a stub server. Decide which operations are safe to retry and explain why.'})]],
['Circuit Breakers and Rate Limits','Now we will stop a failing shipping service from consuming unlimited application capacity. Returning a made-up shipping price would be misleading, so the fallback reports unavailability.',[
s('Three separate protections',['Timeouts bound an individual call. A circuit breaker temporarily refuses calls after enough failures. A rate limiter limits how frequently callers obtain permission. Retries create additional attempts and must have their own budget.']),
s('Put protection on a Spring bean',['ShippingClient.quote has the circuit breaker and rate limiter annotations. ShippingController calls that bean through Spring’s proxy. Calling the annotated method from another method on the same object would bypass that proxy.'],{files:['ShippingClient.java','ShippingController.java']}),
s('Read the fallback',['unavailable accepts the failure and returns an explicit temporary-unavailability message. There is no blanket payment retry annotation: uncertain payment outcomes need the stable key and status reconciliation taught later.']),
s('Observe the failure',['With nothing listening on port 9999, request /api/v1/shipping. Observe the bounded failure and fallback. In a follow-up exercise, configure a small sliding window and inspect when the circuit opens.'],{request:['GET','/api/v1/shipping'],exercise:'Set a low per-second rate limit, send a burst, and distinguish rate-limit rejection from an open circuit.'})]],
['Refresh Tokens and Account Recovery','Now we will complete the login lifecycle. Signing in once is only part of the work: sessions expire, users log out, and passwords get forgotten.',[
s('Access tokens and refresh tokens',['This continuation deliberately uses random opaque bearer tokens stored as hashes. Access tokens last ten minutes; refresh tokens last seven days. This complements the JWT lessons: an opaque token requires a database lookup but makes server-side revocation straightforward.']),
s('Register and verify',['POST /auth/register, then open Mailpit at localhost:8025. Copy the verification token from the message into POST /auth/verify. Verification proves access to the email inbox; it is not another password.'],{files:['AuthController.java','MailService.java']}),
s('Rotate and revoke',['AuthService consumes a refresh token under a row lock, deletes its family’s previous access token, and issues a replacement pair. Reusing the consumed refresh token is rejected. Logout deletes the family. This teaching implementation rejects replay but does not yet revoke every descendant on replay detection.'],{files:['AuthService.java','Security.java']}),
s('Reset a password',['/auth/forgot always returns 202 so its status does not reveal whether an email exists. A reset token expires after fifteen minutes and can be consumed once. Successful reset replaces the BCrypt password and revokes all existing tokens for that account.'],{exercise:'Log in twice, reset the password, and prove that both old access tokens stop working.'})]],
['File Uploads and Downloads','Now we will let an authenticated user attach a PDF. The filename supplied by a browser is input, so it must not choose a path on our server.',[
s('Choose the storage identifier',['Files generates a UUID and stores bytes under that identifier. The original filename is not appended to the storage root. The download path is parsed as UUID and ownership is checked in the database.'],{files:['Files.java']}),
s('Validate the upload',['The server limits multipart size and checks a PDF header. Header checking is only a teaching baseline: a PDF can still contain harmful content. A public deployment needs malware scanning, quarantine and a deliberate retention policy.']),
s('Return a safe download',['The endpoint uses attachment disposition, a fixed display filename and nosniff. A different owner gets 404. Binary bytes are returned as a Resource instead of being embedded into JSON.']),
s('Try the round trip',['In Postman, POST multipart/form-data to /api/v1/files using a file field named file. Copy the returned id and GET /api/v1/files/{id} with the same bearer token.'],{exercise:'Use another account’s token for the download, then try a text file renamed to .pdf. Both should fail.'})]],
['Email Templates and Async Delivery','Now we will send account messages through SMTP and move receipt work outside the request thread. Local Mailpit captures messages without sending to real inboxes.',[
s('Start local email',['Run docker compose up -d mailpit from the continuation folder. SMTP listens on 1025; the inbox UI is at 8025. MAIL_HOST, MAIL_PORT and MAIL_FROM can later point at a real provider. No provider password is committed.'],{files:['MailService.java','../compose.yaml']}),
s('Separate content from transport',['MailService builds a plain-text message and hands it to JavaMailSender. Put reusable subject/body generation in template functions rather than repeating strings in controllers. Never write access or recovery tokens to application logs.']),
s('Call async work through another bean',['ReceiptService.receipt is @Async and must be called from a different Spring bean. The return does not mean the email was delivered. The class is a focused optional example; payment state changes do not depend on SMTP success.'],{files:['ReceiptService.java']}),
s('Understand the durability limit',['An in-memory async task can disappear if the process crashes. For receipts that must eventually be sent, store an outbox record and let a worker deliver it with retry and deduplication. We implement that pattern in the distributed group.'],{exercise:'Replace the plain-text receipt with an HTML template, escape the product name, and test the rendered body before sending.'})]],
['Stripe Payment Integration','Now we will turn an order into a real test-mode checkout. The payment provider collects card details; our application stores the order and verifies the payment result.',[
s('Prepare your test account',['Create a Stripe test account. Set STRIPE_SECRET_KEY and STRIPE_WEBHOOK_SECRET in your local environment. The client deliberately accepts sk_test_ keys only. Do not paste keys into the site, source code, or chat.']),
s('Create checkout from server data',['POST /api/v1/orders/{id}/checkout. PaymentClient sends the stored quantity and a server-defined unit price of 2500 minor USD units. The caller cannot select an arbitrary payable amount. Open the returned URL in your browser.'],{files:['PaymentClient.java','PaymentService.java'],request:['POST','/api/v1/orders/1/checkout']}),
s('Verify the webhook',['Run stripe listen --forward-to localhost:8090/webhooks/stripe and use its signing secret. Payments checks the timestamp and HMAC against the unmodified request body. A browser redirect never marks an order paid. The signed checkout.session.completed event must also report payment_status=paid and match the session, currency and total.'],{files:['Payments.java']}),
s('Make delivery repeatable',['The payment_event table records processed event IDs in the same transaction as the PAID change. Duplicate delivery returns successfully without applying the transition again. The test signs a fixture event and sends it twice.']),
s('Request a refund',['POST /api/v1/orders/{id}/refund for a paid order. The adapter uses a stable refund key. The local state becomes REFUND_PENDING: do not call it refunded until a provider event or reconciliation confirms the final result. This first integration supports immediate checkout completion; delayed payment methods and refund settlement are exercises in the workflow section.'],{exercise:'Complete a Stripe test checkout, verify the signed event changed your order, then request a test refund and inspect its status in the dashboard.'})]],
['RabbitMQ Messaging','Now we will move work between producers and consumers. An application event in one JVM does not survive that JVM or reach another service automatically.',[
s('Start the broker',['Run docker compose up -d rabbit. Activate the broker profile to create durable receipt and dead-letter queues. Local Compose exposes the broker only on loopback. Replace default credentials before any shared deployment.']),
s('Follow acknowledgement and retry',['A listener returning normally allows acknowledgement. A thrown exception causes the configured bounded retry; after exhaustion, rejection routes the message to the dead-letter queue. Durable queues alone do not guarantee that a publisher successfully sent a message.'],{files:['OrderMessages.java','application-broker.properties']}),
s('Handle duplicate delivery',['Consumer records receipt event IDs and its database effect in one transaction. For this small example the effect is a persisted work marker. Real email needs its own delivery record because a database transaction cannot undo a message already accepted by SMTP.']),
s('Publish a sample',['In the RabbitMQ management UI at localhost:15672, publish a text message to the default exchange with routing key commerce.receipts. Use the same event ID twice and check that one work marker is stored. The distributed section adds a confirmed outbox publisher.'],{exercise:'Force the consumer to throw for one event ID. Observe retries and its final arrival in commerce.receipts.dead.'})]],
['Metrics, Logs and Traces','Now we will answer operational questions: how many orders were created, which request failed, and where did its time go?',[
s('Record a business metric',['OrderService increments commerce.orders.created after saving an order. Metrics aggregate counts; do not use order IDs as metric tags because every ID creates another time series. A rolled-back transaction can make an in-transaction counter overcount; a production business counter should be emitted after commit or derived from durable events.'],{files:['OrderService.java']}),
s('Expose operational endpoints',['The project includes Prometheus and tracing bridges. /actuator/health is public; other actuator endpoints require authentication. Fetch /actuator/prometheus with your token and find the order counter.'],{files:['application.properties','pom.xml']}),
s('Distinguish a trace from a log',['A trace links timed spans across services; a correlation ID makes related log lines searchable. Passing an ID does not automatically create a distributed trace. The workflow project explicitly propagates a correlation header; later we add collector/exporter configuration as a deployment choice.']),
s('Investigate one failure',['Send a failing shipping request, inspect its logs, then compare latency and failure metrics. Keep passwords, bearer tokens, card information and recovery codes out of logs.'],{exercise:'Configure an OpenTelemetry collector in your environment and inspect one HTTP request’s spans across two services.'})]],
['CI/CD and Deployment','Now we will make building and releasing repeatable. A successful local launch is not yet a deployment process.',[
s('Build once, deploy the artifact',['The pipeline runs Maven verification, packages the application and builds a container. Use an immutable commit-based image tag when publishing. Do not rebuild a different binary manually on the server.'],{files:['../ci.yml','Dockerfile']}),
s('Move configuration outside the image',['Set database, mail and provider configuration through environment variables or your deployment platform’s secret store. The image contains no payment keys. Public deployments need HTTPS and private access between services.']),
s('Deploy with a rollback plan',['Run migrations as part of the release process, check readiness, then direct traffic to the new version. Favor schema changes compatible with both old and new application versions during a rolling release. Rolling back Java does not automatically undo migrated data.']),
s('Choose hosting when ready',['No cloud login is required for the local project. To deploy it, we will need your preferred platform, registry, domain and a way for you to configure secrets there. The included pipeline builds and tests locally; it does not publish to an account without your choice.'],{exercise:'Build the Docker image, run it with external database settings, and verify health/readiness before testing checkout.'})]],
['Complete Order Application','Now we will connect the features into one user journey. We are going to register, place an order, pay, and inspect the result without bypassing the application’s rules.',[
s('Prepare the application',['Start PostgreSQL and Mailpit if Docker is available. Otherwise the application uses file-backed H2; authentication email still needs an SMTP server. Build commerce with Maven and start its JAR. Swagger UI provides the endpoint reference.']),
s('Follow the complete journey',['Register → verify email in Mailpit → log in → create an order → start Stripe test checkout → receive a signed webhook → read the paid order. Keep the bearer token in Postman authorization rather than adding an owner to the request body.'],{flow:['Account verified','Order PENDING','Checkout created','Signed payment event','Order PAID']}),
s('Exercise the boundaries',['Try invalid quantities, another user’s order ID, a stale version, an unsigned webhook, and a repeated signed event. Then rotate tokens and confirm the old access token no longer works.'],{files:['CommerceTest.java']}),
s('Continue into distributed workflows',['The application currently owns its order database and calls a provider. Next, we split Order, Inventory and Payment into independent processes with separate stores. This changes how we recover; adding @Transactional to the calling method will not cover the other services.'],{exercise:'Write down the order’s local state and the provider’s state when the HTTP response is lost after a successful charge. Carry that scenario into the next group.'})]]
];

const distributed=[
['Distributed Workflow Basics','Now we are going to split checkout across independent services. Each service can commit its own data while another service fails.',[
s('Draw the boundaries',['Order stores workflow progress. Inventory owns reservation state. Payment owns charge state. We run one workflow JAR three times with different roles, ports and database files. This keeps the code small while preserving real process and database boundaries.'],{flow:['Order :8100','Inventory :8101','Payment :8102']}),
s('Why one transaction is insufficient',['A local database rollback cannot undo a request already committed by another process. The caller can also lose the response after the remote commit. A distributed workflow needs durable progress and a recovery policy.']),
s('Start the participants',['Set WORKFLOW_SECRET to the same locally chosen value of at least sixteen characters in all three terminals. Start inventory on 8101 and payment on 8102, then order on 8100. Use the role-specific commands shown below. Each request must carry X-Workflow-Key.'],{files:['application.properties','NodeSecurity.java']}),
s('Keep the payment boundary explicit',['The workflow Payment participant is a deterministic local gateway fixture for failure exercises. It does not charge cards. The previous group’s Stripe adapter is the real test-mode provider integration; replacing the participant requires the same idempotency and reconciliation contract.'],{exercise:'Stop Payment and check that Order can still answer its health endpoint. Explain which boundary failed.'})]],
['HTTP Calls versus Messages','Now we will compare waiting for an immediate HTTP result with delivering a message for another service to process later.',[
s('Synchronous communication',['Orchestrator.effect makes a bounded HTTP call. A response can tell us the participant’s current state, but an exception does not tell us that the operation never happened.'],{files:['Orchestrator.java']}),
s('Asynchronous communication',['With the broker profile and choreography mode, BrokerFlow publishes durable events. The producer can commit before the consumer runs. That introduces delayed outcomes, duplicate delivery and event schema responsibilities.'],{files:['BrokerFlow.java']}),
s('Choose by the use case',['Use HTTP when the caller needs a bounded immediate response. Use messaging when work should remain pending while a consumer is unavailable. Neither choice removes the need for idempotency or durable state.']),
s('Compare both versions',['First run the default HTTP orchestration. Later start RabbitMQ and switch all nodes to broker/choreography. Reuse the same success and failure scenarios so the communication difference is visible.'],{exercise:'Record what the caller sees when Payment is down in each version. Distinguish accepted work from completed work.'})]],
['Order and Payment State Machines','Now we will name the intermediate states. A single success flag cannot describe reserved stock, an uncertain charge, and a pending refund.',[
s('Write legal transitions',['The order path is NEW → RESERVED → CHARGED → COMPLETED. A declined payment moves to RELEASING → CANCELLED. A later failure moves through REFUNDING before release. MANUAL_REVIEW means automatic recovery stopped; it does not mean the payment failed.'],{flow:['NEW','RESERVED','CHARGED','COMPLETED']}),
s('Keep participant states separate',['Inventory uses RESERVED, COMMITTED and RELEASED. Payment uses CHARGED, DECLINED and REFUNDED. A participant result is not automatically the order’s final result.'],{files:['Participant.java']}),
s('Persist before continuing',['WorkflowStore stores progress and appends the state-change event in one local transaction. Orchestrator advances only from the expected phase so a stale update cannot overwrite a newer state.'],{files:['WorkflowStore.java']}),
s('Inspect the workflow',['GET /workflows/{id} returns PHASE, ATTEMPTS and NEXT_ATTEMPT. Read these together when diagnosing a pending workflow.'],{exercise:'Add a transition table to your notes. For each arrow, identify its trigger and the recovery action if its response is lost.'})]],
['Reliable Message Delivery','Now we will follow a message from the producer’s database to the consumer’s committed effect. There are several failure boundaries along that path.',[
s('Confirm publication',['A broker publisher confirm reports broker acceptance. An unroutable return means the message did not reach a queue. Neither proves that a consumer finished the business work. Relay checks both before marking an outbox record sent.'],{files:['BrokerFlow.java']}),
s('Acknowledge consumption',['The listener’s database transaction must complete successfully before its work is considered processed. If acknowledgement is lost after commit, the broker may redeliver. That is why the inbox check is necessary.']),
s('Use durable queues and a dead-letter route',['Each role has a durable queue and a separate dead queue. The broker profile configures bounded listener retry and rejection. A message in the dead queue requires investigation; silently deleting it loses business work.']),
s('Plan for at-least-once delivery',['The supplied relay may publish the same outbox record again after a crash between confirm and the sent update. This is intentional at-least-once behavior, not exactly-once delivery.'],{exercise:'Pause the consumer, publish an event, and restart the consumer. Then redeliver the event and verify one database effect.'})]],
['Idempotent Business Operations','Now we will make repeated requests safe. A retry should repeat our attempt to learn the outcome, not create another charge.',[
s('Choose a business key',['Each workflow has a UUID supplied once by the caller. Participant uses role + workflow ID as its effect key. A repeated reserve or charge returns the existing result instead of inserting a second effect.'],{files:['Participant.java']}),
s('Check the same operation',['Reusing an idempotency key for a different amount or product should be rejected. The small workflow fixture has one fixed reservation per workflow; a real adapter must persist and compare the request fingerprint alongside its key.']),
s('Do not replay obsolete transitions',['After release, a delayed reserve cannot recreate the reservation. Participant validates legal source states and can reject an expected-version mismatch. Same-result retries and stale transitions are different cases.']),
s('Test the repetition',['WorkflowTest repeats reserve and checks that only one row exists. It also proves that reserve cannot undo release.'],{files:['WorkflowTest.java'],exercise:'Send the same charge twice with the same workflow ID, then query Payment and verify one stored effect.'})]],
['Transactional Outbox','Now we will close the gap between committing an order and publishing its event. Sending before or after a database commit leaves a failure window.',[
s('Commit intent with the business change',['WorkflowStore creates the workflow and its OrderCreated outbox row in one database transaction. If that transaction rolls back, neither row exists. The relay sends only committed rows.'],{files:['WorkflowStore.java','schema.sql']}),
s('Publish independently',['Relay reads unsent rows and sends their stored event ID. It waits for publisher confirmation and checks returns before setting sent=true. When the broker is down, the row remains pending for the next pass.'],{files:['BrokerFlow.java']}),
s('Expect the duplicate window',['If the broker accepted the event and the process crashed before updating sent, the row is sent again. Do not attempt to solve this by inventing one transaction spanning JDBC and RabbitMQ; use an idempotent consumer.']),
s('Operate the relay',['GET /workflows/{id}/events shows the local outbox. A production relay needs batching, retention, queue-depth metrics and safe multi-worker claiming. This teaching relay runs one publisher per node.'],{exercise:'Start an order with RabbitMQ stopped, inspect its unsent row, then start RabbitMQ and watch it become sent.'})]],
['Inbox and Idempotent Consumers','Now we will make a repeated delivery harmless at the receiver, even if the sender behaves correctly but its acknowledgement is lost.',[
s('Store processed event IDs',['The inbox table has a primary key on event ID. Handler checks it inside the same transaction as the local effect and the next outbox event. A failure rolls back all three.'],{files:['schema.sql','BrokerFlow.java']}),
s('Scope deduplication correctly',['An inbox belongs to one consumer’s database. Inventory and Payment may both process the same event independently. They must not share one global processed-event flag that prevents the second service from acting.']),
s('Consider concurrent delivery',['The unique constraint is the final protection if two deliveries race past the initial lookup. The losing transaction fails and can retry; its later attempt sees the committed inbox row and exits.']),
s('Keep external effects outside the illusion',['A database inbox cannot roll back an already-sent email or charge. That external operation needs its own stable idempotency key and a durable outcome record.'],{exercise:'Inject an exception after the local effect but before listener return. Verify that rollback leaves no partial effect or inbox marker.'})]],
['Saga Fundamentals','Now we will join local transactions into a business workflow without pretending they are one ACID transaction.',[
s('What is a Saga?',['A Saga is a sequence of local transactions with recovery actions for completed steps. Other requests may observe intermediate states, so the domain must define what pending reservations and payments mean.']),
s('Write compensation beside each step',['Reserve stock → release stock. Charge payment → request refund. Create pending order → cancel order. A refund is a new business operation; it does not erase the original charge.'],{table:{head:['Forward step','Compensation'],rows:[['Reserve inventory','Release reservation'],['Charge payment','Request and confirm refund'],['Create pending order','Mark cancelled']]}}),
s('Find the irreversible boundary',['A completed shipment cannot be undone with a database rollback. Before an irreversible action, define how the business will handle failures: return shipment, customer support or another explicit process.']),
s('Read the implementation',['Orchestrator persists one phase at a time and repeats an uncertain participant call with the same workflow ID. It attempts compensation only after the forward effect is known.'],{files:['Orchestrator.java'],exercise:'Draw a failure after each step and identify which already-completed steps need compensation.'})]],
['Choreography-Based Saga','Now we will let services react to events instead of receiving each instruction from a central coordinator.',[
s('Follow the success chain',['OrderCreated → StockReserved → PaymentCharged → CommitRequested → StockCommitted. Inventory and Payment own their reactions. Order records the final business outcome.'],{flow:['OrderCreated','StockReserved','PaymentCharged','StockCommitted','COMPLETED']}),
s('Run the event version',['Start RabbitMQ. For every process add --spring.profiles.active=broker --workflow.mode=choreography. The HTTP orchestrator stops advancing phases in this mode; BrokerFlow handlers and their outboxes carry the workflow.'],{files:['BrokerFlow.java']}),
s('Follow a payment decline',['Payment emits PaymentDeclined, Inventory releases its reservation and emits StockReleased, then Order marks the workflow CANCELLED. Each handler transaction records its inbox entry and outgoing intent.']),
s('Recognize the tradeoff',['Individual handlers are small, but the overall flow is spread across services. Changing a contract can affect several consumers. Keep the event flow diagram and schema ownership clear.'],{exercise:'Run failPayment=true and inspect each service’s database/logs to explain how cancellation emerged without an HTTP coordinator.'})]],
['Orchestration-Based Saga','Now we will make the coordination explicit. One durable coordinator decides the next command, while participants still own their local data.',[
s('Follow one coordinator tick',['tick selects nonterminal workflows whose next attempt is due. advance reads the stored phase, calls one participant and persists the next phase. Each tick performs one forward or recovery step.'],{files:['Orchestrator.java']}),
s('Keep participant calls idempotent',['A crash can happen after Participant commits but before Order saves its next phase. On restart, the coordinator calls the same operation again. Participant returns the previous result for that stable workflow ID.']),
s('Compare with choreography',['The coordinator makes progress visible in one place and simplifies a sequential flow. It also owns retry policy, versioning and operational recovery. The services remain independent transactions.']),
s('Run the command version',['Use the default orchestration mode without the broker profile. Submit one workflow and poll its phase until COMPLETED. Then compare the same scenario with the event version.'],{exercise:'Explain which process decides to refund after failConfirm=true in each version.'})]],
['Compensation and Refunds','Now the charge succeeded but the order cannot be confirmed. We must recover what has already happened rather than simply throw an exception.',[
s('Compensate in reverse business order',['The fixture enters REFUNDING, confirms the payment participant’s refund result, then releases inventory and cancels the order. If refund fails or its result is unknown, the workflow remains pending; it must not announce cancellation as fully recovered.'],{flow:['CHARGED','REFUNDING','RELEASING','CANCELLED']}),
s('A real refund may be asynchronous',['Stripe may return a pending refund. The commerce application records REFUND_PENDING. A production participant must return final refund success only after a signed event or reconciliation confirms it; an accepted request is insufficient.'],{files:['Orchestrator.java']}),
s('Retain evidence',['Keep the original charge, refund reference and workflow history. Do not delete a payment row to simulate undoing a charge. Compensation may also fail and require staff intervention.']),
s('Try post-charge failure',['Submit a workflow with failConfirm=true. Expect Payment REFUNDED, Inventory RELEASED and Order CANCELLED. The local fixture makes these states deterministic for practice.'],{exercise:'Stop Payment while REFUNDING is pending, then restart it. Verify that the workflow does not release and finish before the refund result is known.'})]],
['Timeouts and Unknown Outcomes','Now the payment call timed out. Did the provider decline it, or did it charge successfully before the response was lost?',[
s('Unknown is not failed',['A timeout describes what the caller observed. It does not prove that the participant rolled back. Starting a new charge with a new key could double-charge the customer.']),
s('Repeat or reconcile',['The fixture repeats the same operation key; the participant returns its stored effect. A real payment adapter should use the gateway’s idempotency mechanism and query the stored provider reference when needed.']),
s('Read the retry state',['On an HTTP exception, advance keeps the same phase, increments ATTEMPTS and sets NEXT_ATTEMPT. It does not automatically release stock as though the charge certainly failed.'],{files:['Orchestrator.java']}),
s('Exercise the lost response',['Add a fixture delay after saving CHARGED, longer than the caller timeout. The caller retries with the same ID. Verify that Payment still has only one charge effect.'],{exercise:'Describe how an operator resolves MANUAL_REVIEW when the payment provider is unavailable for hours.'})]],
['Retries, Dead Letters and Recovery','Now we will put a limit on automatic recovery. Infinite rapid retries can overload the service we are trying to recover.',[
s('Use a retry budget',['The HTTP coordinator uses exponential delay capped at thirty seconds and stops automatic attempts after five failures. These numbers are teaching defaults, not universal payment policies. Business rejection such as DECLINED follows a separate transition.'],{files:['Orchestrator.java']}),
s('Inspect manual review',['MANUAL_REVIEW means inspect participant state, reconcile the gateway, then choose an audited next action. Do not reset attempts and hope an unknown charge disappears. This project deliberately has no unaudited public force-state endpoint.']),
s('Inspect the dead-letter queue',['The broker version retries listener failures three times before dead-letter routing. Fix the cause, inspect the event and current state, then replay with the original event ID. A duplicate must remain safe.'],{files:['application.properties','BrokerFlow.java']}),
s('Recover without losing intent',['Keep outbox rows pending until confirmed. A retry policy is incomplete without alerting and a way to inspect stuck work.'],{exercise:'Make an invalid transition fail repeatedly, locate its dead letter, and explain what must be checked before replay.'})]],
['Durable Workflow State and Restarts','Now we will restart the coordinator halfway through checkout. Progress must survive outside the process heap.',[
s('Persist the state',['The default workflow database is a file under data/{role}. Restart the same role from the same working directory to reuse it. Give each service its own database in a shared deployment.'],{files:['schema.sql','application.properties']}),
s('Resume from committed progress',['A coordinator tick selects persisted nonterminal rows. If the previous process stopped before a transition commit, it repeats the same idempotent command. If it stopped after commit, it continues from the new phase.']),
s('Version the workflow',['Adding a new phase can break older in-flight rows. A production workflow should record a definition version and retain compatible handlers or migrate pending work explicitly. The small project runs one definition version at a time.']),
s('Test an actual restart',['Submit an order while Payment is stopped, wait for RESERVED, stop Order, start Payment, then restart Order with its original database path. Verify completion with one participant effect.'],{exercise:'Repeat the restart during compensation and inspect the retained outbox rows.'})]],
['Payment Webhooks and Reconciliation','Now we will connect asynchronous provider evidence to our local payment record. Webhooks can be delayed, repeated or arrive after the caller has disconnected.',[
s('Verify before trusting',['The commerce webhook verifies the raw body, signature timestamp and HMAC. It also validates the session, currency and amount against the stored order before changing state. Authentication of the event and correctness of the business transition are separate checks.'],{files:['../commerce/Payments.java','../commerce/PaymentService.java']}),
s('Reconcile missing notifications',['Persist the provider object ID when creating checkout or charge. POST /api/v1/orders/{id}/reconcile queries the stored Checkout Session or pending refund. It applies the same amount/currency/session checks for a paid session and confirms REFUNDED only when the refund status is succeeded. Schedule this operation through a bounded worker for automated reconciliation. Do not search by amount alone.']),
s('Adapt the participant contract',['Replace the fixture charge/refund operations with a durable provider-operation record: operation key, request fingerprint, provider reference, pending/final state and last checked time. Return unknown while settlement is pending. Keep provider HTTP outside a long database transaction.']),
s('Test delayed evidence',['Use Stripe CLI test forwarding to deliver a completion twice, then restart the consumer. Inspect one PAID transition. The supplied commerce integration handles immediate checkout completion; adding delayed payment event types must preserve these checks.'],{exercise:'Test the supplied reconciliation endpoint with a local HTTP stub reporting a paid session, then a pending and succeeded refund. Verify that an amount mismatch is rejected.'})]],
['Concurrency, Ordering and Reservation Expiry','Now an old event arrives after a reservation was released. We must reject stale work instead of recreating stock ownership.',[
s('Check state and version',['Participant locks its effect row and checks legal transitions. An optional expectedVersion rejects commands based on an older revision. A repeated request for the same state is idempotent; a request reversing a terminal transition is rejected.'],{files:['Participant.java','WorkflowTest.java']}),
s('Track event meaning',['Event IDs deduplicate delivery. Aggregate revisions detect stale updates. Timestamps alone do not reliably order events across machines. The fixture uses legal-state checks; a larger multi-update aggregate should carry explicit revisions.']),
s('Handle reservation expiry carefully',['The fixture stores expires_at as a teaching field. It does not automatically release reservations while payment may have succeeded. A real expiry worker must coordinate with workflow/payment state, use a compare-and-set transition and reconcile late payment evidence.']),
s('Do not oversell the inventory fixture',['The participant models one reservation record per workflow. It is not a complete stock ledger. For quantity-based stock, add an atomic availability decrement, a unique reservation key and a matching release operation.'],{exercise:'Deliver reserve after release and assert rejection. Then design an expiry race test involving a payment success arriving at the deadline.'})]],
['Tracing a Distributed Workflow','Now we will follow one order across all three processes. A stack trace in Order cannot explain work already running in Payment.',[
s('Propagate a correlation ID',['WorkflowController accepts or creates an ID and stores it with the workflow. Orchestrator passes it in X-Correlation-ID, and BrokerFlow carries it in event payloads. Logs include order, phase and attempt.'],{files:['WorkflowController.java','Orchestrator.java','BrokerFlow.java']}),
s('Add spans to the correlation',['The explicit ID is searchable context, not a full trace. Add Micrometer tracing and a collector/exporter, use instrumented client builders and propagate trace headers across HTTP and message boundaries. Keep business workflow IDs separate from span IDs.']),
s('Watch stuck work',['Track age of pending workflows, outbox backlog, retry counts, manual-review count and refund delay. Do not attach each order ID as a metric label. Use logs or traces to investigate one order.']),
s('Investigate a real scenario',['Submit a workflow with X-Correlation-ID: checkout-demo-1, stop Payment, then search coordinator logs for that ID. Explain the phase and the next retry time.'],{exercise:'Add a collector and capture the reserve and charge calls under one trace. Include trace context in the event envelope when using RabbitMQ.'})]],
['Testing Distributed Failures','Now we will deliberately break checkout. A workflow that only passes the happy path has not demonstrated recovery.',[
s('Test the participant rules',['WorkflowTest covers repeated reserve, stale reverse transitions and version conflicts. CommerceTest covers signed duplicate payment events and ownership. These tests protect local invariants.'],{files:['WorkflowTest.java','../commerce/CommerceTest.java']}),
s('Test real processes',['The continuation verifier starts three Java processes with separate database paths. It checks success, decline and compensation, and restarts the coordinator during pending work. This exercises HTTP boundaries without claiming RabbitMQ or Stripe was available.']),
s('Build a failure matrix',['Test a crash before local commit, after local commit but before response, after broker confirm but before sent marking, and after consumer commit but before acknowledgement. Write the invariant expected in each case.']),
s('Add external integration tests',['Docker is required to run RabbitMQ and PostgreSQL/Testcontainers here. Stripe sandbox tests need your own test account. Keep those results separate from fixture-based tests.'],{exercise:'Add an automated lost-response-after-charge test and assert exactly one stored charge effect.'})]],
['Durable Workflow Engines','Now we will compare our custom database-driven coordinator with a dedicated workflow engine. The business rules stay; the infrastructure responsibilities change.',[
s('What does an engine provide?',['A durable engine records workflow history and schedules retries/timers across worker restarts. Activities still need idempotency because an activity can complete remotely before its acknowledgement reaches the engine.']),
s('Read the Temporal example',['The optional temporal module defines a workflow interface, activity interface, implementation and worker. Each activity delegates to the same HTTP participant contract. A stable workflow ID becomes the operation key.'],{files:['../temporal/CheckoutWorkflow.java','../temporal/CheckoutActivities.java','../temporal/CheckoutWorkflowImpl.java','../temporal/WorkerMain.java']}),
s('Keep workflow code deterministic',['Use workflow APIs for time and timers. Put HTTP, random external state and database work in activities. Version code changes for running histories rather than deploying incompatible workflow logic.']),
s('Run locally when ready',['Start a local Temporal development server on 7233, start WorkerMain, then start a workflow with the supplied ClientMain. This needs a local Temporal server, not a cloud login. The custom HTTP coordinator should be disabled for the same workflow ID.'],{exercise:'Restart the worker after reserve. Observe replay and verify that retrying charge uses the same operation key.'})]],
['Complete Distributed Checkout','Now we will demonstrate the whole workflow and explain its outcome from durable records, rather than relying on the final HTTP response alone.',[
s('Run the success scenario',['Start Inventory, Payment and Order with one shared local workflow key. POST a fresh workflow UUID with both failure flags false. Poll until COMPLETED. Inventory must be COMMITTED and Payment CHARGED.']),
s('Run the decline scenario',['Submit a new UUID with failPayment=true. Expect Payment DECLINED, Inventory RELEASED and Order CANCELLED. Repeating the start request must not create a second workflow.']),
s('Run compensation and restart',['Submit failConfirm=true and inspect REFUNDED and RELEASED participant states. Then stop Payment, start another order, restart Order, restore Payment and verify recovery with its original database.'],{files:['Orchestrator.java','WorkflowStore.java']}),
s('Compare both architectures',['Repeat the scenarios using broker/choreography mode with RabbitMQ. Compare where decisions live, how pending work is inspected, and what must be replayed after failure. Do not run two coordination modes against the same active workflow.'],{flow:['Create order','Reserve','Charge','Commit or compensate','Inspect durable result'],exercise:'Present one success and one failed workflow. Explain every local transaction, message or HTTP call, duplicate defense, compensation and remaining unknown outcome.'})]]
];
module.exports={application,distributed};
